package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.complex.Complex;
import org.apache.commons.math3.transform.*;

/** Rank/folded split R-hat and Geyer initial-positive/monotone multi-chain ESS. */
public final class McmcDiagnostics {
    private McmcDiagnostics(){}
    public record Summary(double mean,double median,double standardDeviation,double lower,double upper,double rankSplitRhat,double bulkEffectiveSampleSize,double tailEffectiveSampleSize,double meanEffectiveSampleSize,double meanMonteCarloSE){}
    public static Summary summarize(double[][] chains,double confidence){
        Inference.confidence(confidence);if(chains==null||chains.length<2||chains[0].length<20)throw new IllegalArgumentException("Diagnostics require at least two equal-length chains with 20 draws each.");int draws=chains[0].length;for(var chain:chains)if(chain.length!=draws||Arrays.stream(chain).anyMatch(x->!Double.isFinite(x)))throw new IllegalArgumentException("MCMC draws must be finite and chains equally sized.");double[] pooled=Arrays.stream(chains).flatMapToDouble(Arrays::stream).sorted().toArray();double mean=Arrays.stream(pooled).average().orElseThrow(),variance=0;for(double value:pooled)variance+=(value-mean)*(value-mean)/(pooled.length-1.0);double median=ClusterSem.quantile(pooled,.5),tail=(1-confidence)/2;double[][] split=split(chains),rank=rankNormalize(split),folded=new double[split.length][split[0].length];for(int c=0;c<split.length;c++)for(int j=0;j<split[c].length;j++)folded[c][j]=Math.abs(split[c][j]-median);double rhat=Math.max(rhat(rank),rhat(rankNormalize(folded))),bulk=ess(rank),meanEss=ess(split);double lower5=ClusterSem.quantile(pooled,.05),upper95=ClusterSem.quantile(pooled,.95);double[][] lower=indicator(split,lower5),upper=indicator(split,upper95);double tailEss=Math.min(ess(lower),ess(upper));return new Summary(mean,median,Math.sqrt(variance),ClusterSem.quantile(pooled,tail),ClusterSem.quantile(pooled,1-tail),rhat,bulk,tailEss,meanEss,meanEss>0?Math.sqrt(variance/meanEss):Double.NaN);
    }
    static double[][] split(double[][] chains){int n=chains[0].length/2;double[][] out=new double[chains.length*2][n];for(int c=0;c<chains.length;c++){System.arraycopy(chains[c],0,out[2*c],0,n);System.arraycopy(chains[c],chains[c].length-n,out[2*c+1],0,n);}return out;}
    static double[][] indicator(double[][] values,double cutoff){double[][] out=new double[values.length][values[0].length];for(int c=0;c<out.length;c++)for(int j=0;j<out[c].length;j++)out[c][j]=values[c][j]<=cutoff?1:0;return out;}
    static double[][] rankNormalize(double[][] values){int n=values[0].length,total=values.length*n;Integer[] order=new Integer[total];for(int j=0;j<total;j++)order[j]=j;Arrays.sort(order,Comparator.comparingDouble(i->values[i/n][i%n]));double[][] out=new double[values.length][n];NormalDistribution normal=new NormalDistribution();int start=0;while(start<total){int end=start+1;double value=values[order[start]/n][order[start]%n];while(end<total&&values[order[end]/n][order[end]%n]==value)end++;double rank=(start+1+end)/2.0,z=normal.inverseCumulativeProbability((rank-.375)/(total+.25));for(int i=start;i<end;i++)out[order[i]/n][order[i]%n]=z;start=end;}return out;}
    static double[] variances(double[][] values){int m=values.length,n=values[0].length;double[] means=new double[m];double w=0;for(int c=0;c<m;c++){means[c]=Arrays.stream(values[c]).average().orElseThrow();for(double x:values[c])w+=(x-means[c])*(x-means[c])/(n-1.0)/m;}double average=Arrays.stream(means).average().orElseThrow(),b=0;for(double x:means)b+=(x-average)*(x-average)*n/(m-1.0);return new double[]{w,(n-1.0)/n*w+b/n};}
    static double rhat(double[][] values){double[] v=variances(values);return v[0]>0?Math.sqrt(v[1]/v[0]):v[1]>0?Double.POSITIVE_INFINITY:Double.NaN;}
    static double ess(double[][] values){int m=values.length,n=values[0].length;double[] variance=variances(values);if(!(variance[0]>0)||!(variance[1]>0)||!Double.isFinite(variance[1]))return 0;double[] covariance=new double[n];for(var chain:values){double[] ac=autocovariance(chain);for(int t=0;t<n;t++)covariance[t]+=ac[t]/m;}double sum=0,previous=Double.POSITIVE_INFINITY;for(int t=0;t+1<n;t+=2){double first=t==0?1:1-(variance[0]-covariance[t])/variance[1],second=1-(variance[0]-covariance[t+1])/variance[1],pair=first+second;if(pair<0)break;pair=Math.min(previous,pair);sum+=pair;previous=pair;}double tau=Math.max(1/Math.log10((double)m*n),-1+2*sum);return Math.min(m*(double)n*Math.log10(m*(double)n),m*(double)n/tau);}
    static double[] autocovariance(double[] values){int length=1;while(length<2*values.length)length*=2;double average=Arrays.stream(values).average().orElseThrow();double[] centered=new double[length];for(int j=0;j<values.length;j++)centered[j]=values[j]-average;var fft=new FastFourierTransformer(DftNormalization.STANDARD);Complex[] frequency=fft.transform(centered,TransformType.FORWARD);for(int j=0;j<frequency.length;j++)frequency[j]=frequency[j].multiply(frequency[j].conjugate());Complex[] inverse=fft.transform(frequency,TransformType.INVERSE);double[] result=new double[values.length];for(int j=0;j<result.length;j++)result[j]=inverse[j].getReal()/values.length;return result;}
}
